CREATE OR REPLACE FUNCTION public.create_marketplace_checkout(_items jsonb,_shipping_address jsonb,_shipping_quote_ids jsonb,_coupon_id uuid DEFAULT NULL,_warranty_id text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_order_id uuid; warranty_price numeric; warranty_title text; tx_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta.'; END IF; IF _warranty_id IS NOT NULL THEN CASE _warranty_id WHEN '1_year' THEN warranty_price:=5;warranty_title:='1 ano'; WHEN '1_5_years' THEN warranty_price:=6;warranty_title:='1 ano e meio'; WHEN '2_years' THEN warranty_price:=7;warranty_title:='2 anos'; ELSE RAISE EXCEPTION 'Garantia inválida.'; END CASE; END IF; v_order_id:=public.create_marketplace_order_v3(_items,_shipping_address,_shipping_quote_ids,_coupon_id); IF warranty_price IS NOT NULL THEN SELECT id INTO tx_id FROM public.payment_transactions WHERE order_id=v_order_id ORDER BY created_at,id LIMIT 1 FOR UPDATE; IF tx_id IS NULL THEN RAISE EXCEPTION 'Pedido sem transação.'; END IF; UPDATE public.orders SET total=total+warranty_price,platform_fee=platform_fee+warranty_price,shipping_address=coalesce(shipping_address,'{}'::jsonb)||jsonb_build_object('warranty',jsonb_build_object('id',_warranty_id,'title',warranty_title,'amount',warranty_price)) WHERE id=v_order_id; UPDATE public.payment_transactions SET gross_amount=gross_amount+warranty_price,platform_fee=platform_fee+warranty_price WHERE id=tx_id; END IF; RETURN v_order_id; END $$;
REVOKE ALL ON FUNCTION public.create_marketplace_checkout(jsonb,jsonb,jsonb,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_marketplace_checkout(jsonb,jsonb,jsonb,uuid,text) TO authenticated;